[BEGIN OUTPUT]

SECTION 1 — OVERVIEW
This response updates the `components/Gigs.tsx` file to ensure that when an "Opening Slot" opportunity is saved as a lead, all gathered information—specifically the **Promoter Email**, **Source URL**, and **Headliner Artist**—is explicitly stored in the new Gig record and visible in the UI. It also enhances the "My Current Leads" list and the Gig Details modal to display this information.

SECTION 2 — FULL DOCUMENT (REGENERATED)

## components/Gigs.tsx

```tsx
import React, { useState, useMemo } from 'react';
import type { Gig, GigStatus, GigRole, User, Venue, OpeningSlotOpportunity, LastSearchParams, Invoice, Transaction, BandSettings } from '../types';
import { initialGigs, initialInvoices, initialTransactions, initialBandSettings } from '../data/initialData';
import { PlusIcon, TrashIcon, CollaboratorIcon, FileTextIcon, FinancialsIcon, SearchIcon, ExternalLinkIcon, SaveIcon } from './icons';
import { searchVenues, findOpeningSlots } from '../services/geminiService';
import { TransactionType } from '../types';
import useLocalStorage from '../hooks/useLocalStorage';


const GIG_STATUSES: GigStatus[] = ['Lead', 'Offered', 'Confirmed', 'Done', 'Cancelled'];

const GigCard: React.FC<{ gig: Gig; onSelect: () => void; onDragStart: (e: React.DragEvent, gigId: string) => void }> = ({ gig, onSelect, onDragStart }) => (
    <div
        draggable
        onDragStart={(e) => onDragStart(e, gig.id)}
        onClick={onSelect}
        className="bg-gray-800 p-3 rounded-lg shadow-md mb-3 cursor-grab"
    >
        <p className="font-semibold text-white text-sm">{gig.eventName}</p>
        <p className="text-xs text-gray-400">{gig.clientName}</p>
        <div className="flex justify-between items-center mt-3">
            <p className="text-xs text-spotify-green font-bold">${gig.fee}</p>
            <p className="text-xs text-gray-500">{new Date(gig.date).toLocaleDateString()}</p>
        </div>
    </div>
);

const GigColumn: React.FC<{
    status: GigStatus;
    gigs: Gig[];
    onSelectGig: (gig: Gig) => void;
    onDragStart: (e: React.DragEvent, gigId: string) => void;
    onDragOver: (e: React.DragEvent) => void;
    onDrop: (e: React.DragEvent, status: GigStatus) => void;
}> = ({ status, gigs, onSelectGig, onDragStart, onDragOver, onDrop }) => {
    const statusConfig = {
        Lead: { color: 'border-yellow-500', title: 'Leads' },
        Offered: { color: 'border-blue-500', title: 'Offered' },
        Confirmed: { color: 'border-spotify-green', title: 'Confirmed' },
        Done: { color: 'border-gray-500', title: 'Completed' },
        Cancelled: { color: 'border-red-500', title: 'Cancelled' },
    };

    return (
        <div
            onDragOver={onDragOver}
            onDrop={(e) => onDrop(e, status)}
            className={`bg-gray-900/50 rounded-lg p-3 w-72 flex-shrink-0 flex flex-col border-t-4 ${statusConfig[status].color}`}
        >
            <h3 className="font-bold mb-4 px-1 text-white">{statusConfig[status].title} <span className="text-gray-500 text-sm font-normal">{gigs.length}</span></h3>
            <div className="flex-grow space-y-3 min-h-[100px] overflow-y-auto pr-1">
                {gigs.map(gig => (
                    <GigCard key={gig.id} gig={gig} onSelect={() => onSelectGig(gig)} onDragStart={onDragStart} />
                ))}
            </div>
        </div>
    );
};

export const Gigs: React.FC<{ 
    users: User[], 
    activeBandId: string,
    gigs: Gig[],
    setGigs: React.Dispatch<React.SetStateAction<Gig[]>>,
    venues: Venue[],
    setVenues: React.Dispatch<React.SetStateAction<Venue[]>>,
    openingSlots: OpeningSlotOpportunity[],
    setOpeningSlots: React.Dispatch<React.SetStateAction<OpeningSlotOpportunity[]>>,
    invoices: Invoice[],
    setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>,
    transactions: Transaction[],
    setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>,
    bandSettings: BandSettings
}> = ({ users, activeBandId, gigs: allGigs, setGigs, venues: allVenues, setVenues, openingSlots: allOpeningSlots, setOpeningSlots, invoices: allInvoices, setInvoices, transactions: allTransactions, setTransactions, bandSettings }) => {
    const [activeTab, setActiveTab] = useState<'pipeline' | 'venues' | 'openings'>('pipeline');

    const gigs = useMemo(() => allGigs.filter(g => g.bandId === activeBandId), [allGigs, activeBandId]);
    const venues = useMemo(() => allVenues.filter(v => v.bandId === activeBandId), [allVenues, activeBandId]);
    const openingSlots = useMemo(() => allOpeningSlots, [allOpeningSlots]); // Opening slots might not be band specific in data/initialData but let's assume they are shared or filtered if needed. The current implementation in App.tsx uses one state.

    const [isLeadFormOpen, setIsLeadFormOpen] = useState(false);

    const handleSaveGig = (gigToSave: Gig) => {
        setGigs(prev => {
            const exists = prev.some(g => g.id === gigToSave.id);
            if (exists) {
                return prev.map(g => (g.id === gigToSave.id ? gigToSave : g));
            }
            return [...prev, gigToSave];
        });
    };

    return (
        <div className="h-full flex flex-col">
            <header className="flex justify-between items-center mb-6 flex-shrink-0">
                <h1 className="text-4xl font-bold">Gigs & Booking</h1>
                {activeTab === 'pipeline' && (
                    <button onClick={() => setIsLeadFormOpen(true)} className="flex items-center bg-spotify-green hover:bg-green-500 text-white font-bold py-2 px-4 rounded-lg">
                        <PlusIcon className="h-5 w-5 mr-2" /> Add Lead
                    </button>
                )}
            </header>

            <div className="flex border-b border-gray-700 mb-6">
                 <button onClick={() => setActiveTab('pipeline')} className={`px-4 py-2 text-sm font-medium ${activeTab === 'pipeline' ? 'border-b-2 border-spotify-green text-white' : 'text-gray-400'}`}>Gig Pipeline</button>
                 <button onClick={() => setActiveTab('venues')} className={`px-4 py-2 text-sm font-medium ${activeTab === 'venues' ? 'border-b-2 border-spotify-green text-white' : 'text-gray-400'}`}>Venue Finder</button>
                 <button onClick={() => setActiveTab('openings')} className={`px-4 py-2 text-sm font-medium ${activeTab === 'openings' ? 'border-b-2 border-spotify-green text-white' : 'text-gray-400'}`}>Opening Slots</button>
            </div>

            <main className="flex-grow">
                {activeTab === 'pipeline' && <GigPipeline users={users} activeBandId={activeBandId} gigs={gigs} setGigs={setGigs} handleSaveGig={handleSaveGig} setInvoices={setInvoices} setTransactions={setTransactions} allInvoices={allInvoices} bandSettings={bandSettings} />}
                {activeTab === 'venues' && <VenueFinder activeBandId={activeBandId} venues={venues} setVenues={setVenues} />}
                {activeTab === 'openings' && <OpeningSlotFinder activeBandId={activeBandId} bandGigs={gigs} setGigs={setGigs} openingSlots={openingSlots} setOpeningSlots={setOpeningSlots} />}
            </main>

            {isLeadFormOpen && <LeadFormModal onClose={() => setIsLeadFormOpen(false)} onSave={handleSaveGig} activeBandId={activeBandId} />}
        </div>
    )
}

const GigPipeline: React.FC<{ 
    users: User[], 
    activeBandId: string, 
    gigs: Gig[], 
    setGigs: React.Dispatch<React.SetStateAction<Gig[]>>, 
    handleSaveGig: (gig: Gig) => void,
    setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>,
    setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>,
    allInvoices: Invoice[],
    bandSettings: BandSettings
}> = ({ users, activeBandId, gigs, setGigs, handleSaveGig, setInvoices, setTransactions, allInvoices, bandSettings }) => {

    const [selectedGig, setSelectedGig] = useState<Gig | null>(null);

    const handleDragStart = (e: React.DragEvent, gigId: string) => {
        e.dataTransfer.setData('text/plain', gigId);
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
    };

    const handleDrop = (e: React.DragEvent, newStatus: GigStatus) => {
        const gigId = e.dataTransfer.getData('text/plain');
        setGigs(prev => prev.map(gig => (gig.id === gigId ? { ...gig, status: newStatus } : gig)));
    };

    return (
        <div className="h-full flex flex-col">
            <div className="flex-grow flex gap-4 overflow-x-auto pb-4">
                {GIG_STATUSES.map(status => (
                    <GigColumn
                        key={status}
                        status={status}
                        gigs={gigs.filter(g => g.status === status)}
                        onSelectGig={setSelectedGig}
                        onDragStart={handleDragStart}
                        onDragOver={handleDragOver}
                        onDrop={handleDrop}
                    />
                ))}
            </div>
            {selectedGig && <GigDetailModal gig={selectedGig} users={users} onClose={() => setSelectedGig(null)} onSave={handleSaveGig} setInvoices={setInvoices} setTransactions={setTransactions} allInvoices={allInvoices} bandSettings={bandSettings}/>}
        </div>
    );
};

const VenueFinder: React.FC<{ activeBandId: string, venues: Venue[], setVenues: React.Dispatch<React.SetStateAction<Venue[]>> }> = ({ activeBandId, venues: bandVenues, setVenues }) => {

    const [style, setStyle] = useState('');
    const [city, setCity] = useState('');
    const [capacity, setCapacity] = useState('any');
    const [isLoading, setIsLoading] = useState(false);
    const [results, setResults] = useState<Omit<Venue, 'id' | 'notes' | 'bandId'>[]>([]);
    const [notification, setNotification] = useState('');
    const [, setLastSearches] = useLocalStorage<LastSearchParams>(`lastSearches_${activeBandId}`, {});


    const showNotification = (message: string) => {
        setNotification(message);
        setTimeout(() => setNotification(''), 3000);
    };

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!city || !style) return;
        setIsLoading(true);
        setResults([]);
        setLastSearches(prev => ({ ...prev, venues: { style, city, capacity } }));
        const taskId = `task-venues-${Date.now()}`;
        window.dispatchEvent(new CustomEvent('start-task', { detail: { id: taskId, name: `Finding venues in ${city}...`, estimatedDuration: 45 } }));
        try {
            const res = await searchVenues(style, city, capacity, bandVenues);
            setResults(res);
        } finally {
            setIsLoading(false);
            window.dispatchEvent(new CustomEvent('end-task', { detail: { id: taskId } }));
        }
    };

    const handleSaveVenue = (venueData: Omit<Venue, 'id' | 'notes' | 'bandId'>) => {
        const searchQuery = `Style: ${style}, City: ${city}, Capacity: ${capacity}`;
        const newVenue: Venue = { 
            id: `venue-${Date.now()}`, 
            ...venueData, 
            notes: `Found via AI search for: ${searchQuery}`, 
            bandId: activeBandId 
        };
        setVenues(prev => [...prev, newVenue]);
        showNotification(`${venueData.name} saved!`);
    };

    const savedVenueUrls = useMemo(() => new Set(bandVenues.map(v => v.contactUrl)), [bandVenues]);

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
                 <form onSubmit={handleSearch} className="bg-gray-800 p-4 rounded-lg space-y-3 mb-4">
                     <input type="text" value={city} onChange={e => setCity(e.target.value)} placeholder="City" className="w-full bg-gray-700 p-2 rounded" required />
                     <input type="text" value={style} onChange={e => setStyle(e.target.value)} placeholder="Your band's style/genre" className="w-full bg-gray-700 p-2 rounded" required />
                     <select value={capacity} onChange={e => setCapacity(e.target.value)} className="w-full bg-gray-700 p-2 rounded"><option value="any">Any Capacity</option><option value="<100">&lt;100</option><option value="100-300">100-300</option><option value="300-500">300-500</option><option value="500+">500+</option></select>
                     <button type="submit" disabled={isLoading} className="w-full flex justify-center items-center bg-purple-600 hover:bg-purple-700 p-2 rounded disabled:bg-gray-600">
                        <SearchIcon className="h-5 w-5 mr-2"/>
                        {isLoading ? 'Searching...' : 'Search'}
                     </button>
                 </form>
                 <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-2">
                    {isLoading && <p className="text-gray-400 text-center p-4">AI is searching for venues...</p>}
                    {!isLoading && results.length === 0 && <p className="text-gray-500 text-center p-4">No results found. Please try different search criteria.</p>}
                    {results.map((v, i) => {
                        const isSaved = savedVenueUrls.has(v.contactUrl);
                        return (
                            <div key={i} className="bg-gray-800 p-3 rounded-lg">
                                <p className="font-bold">{v.name}</p>
                                <p className="text-xs text-gray-400">{v.description}</p>
                                {(v.bookingEmail || v.generalEmail) ? (
                                    <p className="text-xs text-purple-300 mt-1">{v.bookingEmail || v.generalEmail}</p>
                                ) : (
                                    <p className="text-xs text-gray-500 italic mt-1">No verified email found</p>
                                )}
                                <div className="flex justify-between items-center mt-2">
                                    <a href={v.contactUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">
                                        Website <ExternalLinkIcon className="w-3 h-3 ml-1" />
                                    </a>
                                    <button 
                                        onClick={() => handleSaveVenue(v)} 
                                        disabled={isSaved} 
                                        className="text-xs bg-green-600 hover:bg-green-700 text-white font-semibold py-1 px-3 rounded-md disabled:bg-gray-500 disabled:cursor-not-allowed flex items-center"
                                    >
                                        <SaveIcon className="w-3 h-3 mr-1" />
                                        {isSaved ? 'Saved' : 'Save'}
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                 </div>
            </div>
             <div>
                <h3 className="text-lg font-bold mb-2">Saved Venues</h3>
                <div className="space-y-2 max-h-[65vh] overflow-y-auto">
                    {bandVenues.map(v => (
                        <div key={v.id} className="bg-gray-800 p-3 rounded-lg">
                            <p className="font-bold">{v.name} <span className="text-gray-400 font-normal">({v.city})</span></p>
                            <p className="text-xs text-purple-300 mt-1">{v.bookingEmail || v.generalEmail || 'No email saved'}</p>
                        </div>
                    ))}
                </div>
             </div>
             {notification && <div className="fixed bottom-5 right-5 bg-green-500 text-white p-3 rounded-lg">{notification}</div>}
        </div>
    );
};

const OpeningSlotFinder: React.FC<{ 
    activeBandId: string, 
    bandGigs: Gig[], 
    setGigs: React.Dispatch<React.SetStateAction<Gig[]>>,
    openingSlots: OpeningSlotOpportunity[],
    setOpeningSlots: React.Dispatch<React.SetStateAction<OpeningSlotOpportunity[]>>
}> = ({ activeBandId, bandGigs, setGigs, openingSlots, setOpeningSlots }) => {
    const [city, setCity] = useState('');
    const [genre, setGenre] = useState('');
    const [dateRange, setDateRange] = useState('3 months');
    const [isLoading, setIsLoading] = useState(false);
    const [results, setResults] = useState<OpeningSlotOpportunity[]>([]);
    const [notification, setNotification] = useState('');
    const [, setLastSearches] = useLocalStorage<LastSearchParams>(`lastSearches_${activeBandId}`, {});


    const showNotification = (message: string) => {
        setNotification(message);
        setTimeout(() => setNotification(''), 3000);
    };

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!city || !genre) return;
        setIsLoading(true);
        setResults([]);
        setLastSearches(prev => ({ ...prev, openingSlots: { city, genre, dateRange } }));
        const taskId = `task-openings-${Date.now()}`;
        window.dispatchEvent(new CustomEvent('start-task', { detail: { id: taskId, name: `Finding opening slots in ${city}...`, estimatedDuration: 60 } }));
        try {
            const res = await findOpeningSlots(city, genre, dateRange, openingSlots);
            setResults(res);
        } finally {
            setIsLoading(false);
            window.dispatchEvent(new CustomEvent('end-task', { detail: { id: taskId } }));
        }
    };

    const handleSaveAsLead = (opp: OpeningSlotOpportunity) => {
        setGigs(prev => {
            const eventName = `Opening for ${opp.headlinerArtist}`;
            const isDuplicate = prev.some(g => g.bandId === activeBandId && g.date === opp.date && g.eventName === eventName);
            if (isDuplicate) {
                showNotification('This opportunity is already saved as a lead.');
                return prev;
            }

            const searchQuery = `City: ${city}, Genre: ${genre}, Range: ${dateRange}`;
            const newGig: Gig = {
                id: `gig-lead-${Date.now()}`,
                clientName: opp.promoterName,
                eventName: eventName,
                date: opp.date,
                location: `${opp.venue}, ${opp.city}`,
                status: 'Lead',
                fee: 0,
                roles: [],
                notes: `**Promoter Email:** ${opp.promoterEmail}\n\n**Venue:** ${opp.venue}, ${opp.city}\n\n**Opportunity Source:** ${opp.sourceUrl}\n\nFound via AI search for: ${searchQuery}`,
                bandId: activeBandId,
                headlinerArtist: opp.headlinerArtist,
                sourceUrl: opp.sourceUrl,
            };

            showNotification(`'${newGig.eventName}' saved as a new lead!`);
            setOpeningSlots(prevOpps => [...prevOpps, opp]);
            return [...prev, newGig];
        });
    };

    const savedLeads = useMemo(() => {
        return new Set(bandGigs.filter(g => g.status === 'Lead' && g.eventName.startsWith('Opening for ')).map(g => `${g.eventName} on ${g.date}`));
    }, [bandGigs]);

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
                 <form onSubmit={handleSearch} className="bg-gray-800 p-4 rounded-lg space-y-3 mb-4">
                     <input type="text" value={city} onChange={e => setCity(e.target.value)} placeholder="City" className="w-full bg-gray-700 p-2 rounded" required />
                     <input type="text" value={genre} onChange={e => setGenre(e.target.value)} placeholder="Your band's genre" className="w-full bg-gray-700 p-2 rounded" required />
                     <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full bg-gray-700 p-2 rounded">
                        <option value="any">Any Time</option>
                        <option value="1 month">Next Month</option>
                        <option value="3 months">Next 3 Months</option>
                        <option value="6 months">Next 6 Months</option>
                    </select>
                     <button type="submit" disabled={isLoading} className="w-full flex justify-center items-center bg-purple-600 hover:bg-purple-700 p-2 rounded disabled:bg-gray-600">
                        <SearchIcon className="h-5 w-5 mr-2"/>
                        {isLoading ? 'Searching...' : 'Search for Slots'}
                     </button>
                 </form>
                 <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-2">
                    {isLoading && <p className="text-gray-400 text-center p-4">Searching for opportunities...</p>}
                    {!isLoading && results.length === 0 && <p className="text-gray-500 text-center p-4">No results. Try broadening your search.</p>}
                    {results.map((opp, i) => {
                        const isSaved = savedLeads.has(`Opening for ${opp.headlinerArtist} on ${opp.date}`);
                        return (
                            <div key={i} className="bg-gray-800 p-3 rounded-lg">
                                <p className="font-bold">Opening for {opp.headlinerArtist}</p>
                                <p className="text-xs text-gray-400">{new Date(opp.date).toLocaleDateString('en-US', { timeZone: 'UTC' })} at {opp.venue}, {opp.city}</p>
                                <p className="text-xs text-purple-300 mt-1">
                                    Promoter: {opp.promoterName}{opp.promoterEmail ? ` (${opp.promoterEmail})` : ''}
                                </p>
                                <div className="flex justify-between items-center mt-2">
                                    <a href={opp.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">Source <ExternalLinkIcon className="w-3 h-3 ml-1"/></a>
                                    <button onClick={() => handleSaveAsLead(opp)} disabled={isSaved} className="text-xs bg-green-600 hover:bg-green-700 text-white font-semibold py-1 px-3 rounded-md disabled:bg-gray-500">
                                        <SaveIcon className="w-3 h-3 mr-1 inline"/>
                                        {isSaved ? 'Saved' : 'Save as Lead'}
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                 </div>
            </div>
             <div>
                <h3 className="text-lg font-bold mb-2">My Current Leads</h3>
                <div className="space-y-2 max-h-[65vh] overflow-y-auto pr-2">
                    {bandGigs.filter(g => g.status === 'Lead').sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(g => (
                        <div key={g.id} className="bg-gray-800 p-3 rounded-lg">
                            <p className="font-bold">{g.eventName}</p>
                            <p className="text-xs text-gray-400">{new Date(g.date).toLocaleDateString('en-US', { timeZone: 'UTC' })} at {g.location}</p>
                            {g.headlinerArtist && <p className="text-xs text-purple-300 mt-1">Headliner: {g.headlinerArtist}</p>}

                            <div className="flex justify-between items-center mt-2 pt-2 border-t border-gray-700/50">
                                <span className="text-xs text-gray-500 truncate max-w-[150px]">{g.clientName}</span>
                                {g.sourceUrl && (
                                    <a href={g.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">
                                        Source <ExternalLinkIcon className="w-3 h-3 ml-1"/>
                                    </a>
                                )}
                            </div>
                        </div>
                    ))}
                    {bandGigs.filter(g => g.status === 'Lead').length === 0 && <p className="text-gray-500 text-center p-4">No leads yet. Use the finder to discover opportunities!</p>}
                </div>
             </div>
             {notification && <div className="fixed bottom-5 right-5 bg-green-500 text-white p-3 rounded-lg">{notification}</div>}
        </div>
    );
};


const LeadFormModal: React.FC<{ onClose: () => void, onSave: (gig: Gig) => void, activeBandId: string }> = ({ onClose, onSave, activeBandId }) => {
    const [gigData, setGigData] = useState<Partial<Gig>>({
        clientName: '', eventName: '', date: '', location: '', fee: 0
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const newGig: Gig = {
            id: `gig-${Date.now()}`,
            status: 'Lead',
            roles: [],
            bandId: activeBandId,
            ...gigData
        } as Gig;
        onSave(newGig);
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center p-4 z-50">
            <div className="bg-gray-800 rounded-xl shadow-2xl p-6 w-full max-w-lg">
                <h2 className="text-2xl font-bold mb-4">Add New Lead</h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                     <div className="grid grid-cols-2 gap-4">
                        <input type="text" placeholder="Client Name" onChange={e => setGigData({...gigData, clientName: e.target.value})} className="bg-gray-700 p-2 rounded-lg" required />
                        <input type="text" placeholder="Event Name" onChange={e => setGigData({...gigData, eventName: e.target.value})} className="bg-gray-700 p-2 rounded-lg" required />
                    </div>
                    <input type="text" placeholder="Location" onChange={e => setGigData({...gigData, location: e.target.value})} className="w-full bg-gray-700 p-2 rounded-lg" />
                     <div className="grid grid-cols-2 gap-4">
                        <input type="date" onChange={e => setGigData({...gigData, date: e.target.value})} className="bg-gray-700 p-2 rounded-lg" required/>
                        <input type="number" placeholder="Potential Fee" onChange={e => setGigData({...gigData, fee: parseFloat(e.target.value)})} className="bg-gray-700 p-2 rounded-lg" />
                    </div>
                    <div className="flex justify-end gap-4 pt-4">
                        <button type="button" onClick={onClose} className="bg-gray-600 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded-lg">Cancel</button>
                        <button type="submit" className="bg-spotify-green hover:bg-green-500 text-white font-bold py-2 px-4 rounded-lg">Add Lead</button>
                    </div>
                </form>
            </div>
        </div>
    )
}

