const VenueFinder: React.FC<{ activeBandId: string, venues: Venue[], setVenues: React.Dispatch<React.SetStateAction<Venue[]>> }> = ({ activeBandId, venues: bandVenues, setVenues }) => {

    const [style, setStyle] = useState('');
    const [city, setCity] = useState('');
    const [capacity, setCapacity] = useState('any');
    const [isLoading, setIsLoading] = useState(false);
    const [results, setResults] = useState<Omit<Venue, 'id' | 'notes' | 'bandId'>[]>([]);
    const [notification, setNotification] = useState('');
    const [, setLastSearches] = useLocalStorage<LastSearchParams>(`lastSearches_${activeBandId}`, {});


    const showNotification = (message: string) => {
        setNotification(message);
        setTimeout(() => setNotification(''), 3000);
    };

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!city || !style) return;
        setIsLoading(true);
        setResults([]);
        setLastSearches(prev => ({ ...prev, venues: { style, city, capacity } }));
        const taskId = `task-venues-${Date.now()}`;
        window.dispatchEvent(new CustomEvent('start-task', { detail: { id: taskId, name: `Finding venues in ${city}...`, estimatedDuration: 45 } }));
        try {
            const res = await searchVenues(style, city, capacity, bandVenues);
            setResults(res);
        } finally {
            setIsLoading(false);
            window.dispatchEvent(new CustomEvent('end-task', { detail: { id: taskId } }));
        }
    };

    const handleSaveVenue = (venueData: Omit<Venue, 'id' | 'notes' | 'bandId'>) => {
        const searchQuery = `Style: ${style}, City: ${city}, Capacity: ${capacity}`;
        const newVenue: Venue = { 
            id: `venue-${Date.now()}`, 
            ...venueData, 
            notes: `Found via AI search for: ${searchQuery}`, 
            bandId: activeBandId 
        };
        setVenues(prev => [...prev, newVenue]);
        showNotification(`${venueData.name} saved!`);
    };

    const handleDeleteVenue = (venueId: string) => {
        setVenues(prev => prev.filter(v => v.id !== venueId));
    };

    const savedVenueUrls = useMemo(() => new Set(bandVenues.map(v => v.contactUrl)), [bandVenues]);

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
                 <form onSubmit={handleSearch} className="bg-gray-800 p-4 rounded-lg space-y-3 mb-4">
                     <input type="text" value={city} onChange={e => setCity(e.target.value)} placeholder="City" className="w-full bg-gray-700 p-2 rounded" required />
                     <input type="text" value={style} onChange={e => setStyle(e.target.value)} placeholder="Your band's style/genre" className="w-full bg-gray-700 p-2 rounded" required />
                     <select value={capacity} onChange={e => setCapacity(e.target.value)} className="w-full bg-gray-700 p-2 rounded"><option value="any">Any Capacity</option><option value="<100">&lt;100</option><option value="100-300">100-300</option><option value="300-500">300-500</option><option value="500+">500+</option></select>
                     <button type="submit" disabled={isLoading} className="w-full flex justify-center items-center bg-purple-600 hover:bg-purple-700 p-2 rounded disabled:bg-gray-600">
                        <SearchIcon className="h-5 w-5 mr-2"/>
                        {isLoading ? 'Searching...' : 'Search'}
                     </button>
                 </form>
                 <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-2">
                    {isLoading && <p className="text-gray-400 text-center p-4">AI is searching for venues...</p>}
                    {!isLoading && results.length === 0 && <p className="text-gray-500 text-center p-4">No results found. Please try different search criteria.</p>}
                    {results.map((v, i) => {
                        const isSaved = savedVenueUrls.has(v.contactUrl);
                        return (
                            <div key={i} className="bg-gray-800 p-3 rounded-lg">
                                <p className="font-bold">{v.name}</p>
                                <p className="text-xs text-gray-400">{v.description}</p>
                                {(v.bookingEmail || v.generalEmail) ? (
                                    <p className="text-xs text-purple-300 mt-1">{v.bookingEmail || v.generalEmail}</p>
                                ) : (
                                    <p className="text-xs text-gray-500 italic mt-1">No verified email found</p>
                                )}
                                <div className="flex justify-between items-center mt-2">
                                    <a href={v.contactUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">
                                        Website <ExternalLinkIcon className="w-3 h-3 ml-1" />
                                    </a>
                                    <button 
                                        onClick={() => handleSaveVenue(v)} 
                                        disabled={isSaved} 
                                        className="text-xs bg-green-600 hover:bg-green-700 text-white font-semibold py-1 px-3 rounded-md disabled:bg-gray-500 disabled:cursor-not-allowed flex items-center"
                                    >
                                        <SaveIcon className="w-3 h-3 mr-1" />
                                        {isSaved ? 'Saved' : 'Save'}
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                 </div>
            </div>
             <div>
                <h3 className="text-lg font-bold mb-2">Saved Venues</h3>
                <div className="space-y-2 max-h-[65vh] overflow-y-auto">
                    {bandVenues.map(v => (
                        <div key={v.id} className="bg-gray-800 p-3 rounded-lg flex justify-between items-start">
                            <div>
                                <p className="font-bold">{v.name} <span className="text-gray-400 font-normal">({v.city})</span></p>
                                <p className="text-xs text-purple-300 mt-1">{v.bookingEmail || v.generalEmail || 'No email saved'}</p>
                            </div>
                            <button onClick={() => handleDeleteVenue(v.id)} className="p-1 hover:bg-gray-700 rounded"><TrashIcon className="w-4 h-4 text-red-500"/></button>
                        </div>
                    ))}
                </div>
             </div>
             {notification && <div className="fixed bottom-5 right-5 bg-green-500 text-white p-3 rounded-lg">{notification}</div>}
        </div>
    );
};

const OpeningSlotFinder: React.FC<{ 
    activeBandId: string, 
    bandGigs: Gig[], 
    setGigs: React.Dispatch<React.SetStateAction<Gig[]>>,
    openingSlots: OpeningSlotOpportunity[],
    setOpeningSlots: React.Dispatch<React.SetStateAction<OpeningSlotOpportunity[]>>
}> = ({ activeBandId, bandGigs, setGigs, openingSlots, setOpeningSlots }) => {
    const [city, setCity] = useState('');
    const [genre, setGenre] = useState('');
    const [dateRange, setDateRange] = useState('3 months');
    const [isLoading, setIsLoading] = useState(false);
    const [results, setResults] = useState<OpeningSlotOpportunity[]>([]);
    const [notification, setNotification] = useState('');
    const [, setLastSearches] = useLocalStorage<LastSearchParams>(`lastSearches_${activeBandId}`, {});


    const showNotification = (message: string) => {
        setNotification(message);
        setTimeout(() => setNotification(''), 3000);
    };

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!city || !genre) return;
        setIsLoading(true);
        setResults([]);
        setLastSearches(prev => ({ ...prev, openingSlots: { city, genre, dateRange } }));
        const taskId = `task-openings-${Date.now()}`;
        window.dispatchEvent(new CustomEvent('start-task', { detail: { id: taskId, name: `Finding opening slots in ${city}...`, estimatedDuration: 60 } }));
        try {
            const res = await findOpeningSlots(city, genre, dateRange, openingSlots);
            setResults(res);
        } finally {
            setIsLoading(false);
            window.dispatchEvent(new CustomEvent('end-task', { detail: { id: taskId } }));
        }
    };

    const handleSaveAsLead = (opp: OpeningSlotOpportunity) => {
        setGigs(prev => {
            const eventName = `Opening for ${opp.headlinerArtist}`;
            const isDuplicate = prev.some(g => g.bandId === activeBandId && g.date === opp.date && g.eventName === eventName);
            if (isDuplicate) {
                showNotification('This opportunity is already saved as a lead.');
                return prev;
            }

            const searchQuery = `City: ${city}, Genre: ${genre}, Range: ${dateRange}`;
            const newGig: Gig = {
                id: `gig-lead-${Date.now()}`,
                clientName: opp.promoterName,
                eventName: eventName,
                date: opp.date,
                location: `${opp.venue}, ${opp.city}`,
                status: 'Lead',
                fee: 0,
                roles: [],
                notes: `**Promoter Email:** ${opp.promoterEmail}\n\n**Venue:** ${opp.venue}, ${opp.city}\n\n**Opportunity Source:** ${opp.sourceUrl}\n\nFound via AI search for: ${searchQuery}`,
                bandId: activeBandId,
                headlinerArtist: opp.headlinerArtist,
                sourceUrl: opp.sourceUrl,
            };

            showNotification(`'${newGig.eventName}' saved as a new lead!`);
            // Note: OpeningSlotOpportunity doesn't have an ID, so we rely on the Gig ID or a compound key if we wanted to manage them separately.
            // For now, we just add it to the state. Ideally, OpeningSlotOpportunity should have an ID if we want to delete them individually before saving as gig.
            setOpeningSlots(prevOpps => [...prevOpps, opp]); 
            return [...prev, newGig];
        });
    };

    const savedLeads = useMemo(() => {
        return new Set(bandGigs.filter(g => g.status === 'Lead' && g.eventName.startsWith('Opening for ')).map(g => `${g.eventName} on ${g.date}`));
    }, [bandGigs]);

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
                 <form onSubmit={handleSearch} className="bg-gray-800 p-4 rounded-lg space-y-3 mb-4">
                     <input type="text" value={city} onChange={e => setCity(e.target.value)} placeholder="City" className="w-full bg-gray-700 p-2 rounded" required />
                     <input type="text" value={genre} onChange={e => setGenre(e.target.value)} placeholder="Your band's genre" className="w-full bg-gray-700 p-2 rounded" required />
                     <select value={dateRange} onChange={e => setDateRange(e.target.value)} className="w-full bg-gray-700 p-2 rounded">
                        <option value="any">Any Time</option>
                        <option value="1 month">Next Month</option>
                        <option value="3 months">Next 3 Months</option>
                        <option value="6 months">Next 6 Months</option>
                    </select>
                     <button type="submit" disabled={isLoading} className="w-full flex justify-center items-center bg-purple-600 hover:bg-purple-700 p-2 rounded disabled:bg-gray-600">
                        <SearchIcon className="h-5 w-5 mr-2"/>
                        {isLoading ? 'Searching...' : 'Search for Slots'}
                     </button>
                 </form>
                 <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-2">
                    {isLoading && <p className="text-gray-400 text-center p-4">Searching for opportunities...</p>}
                    {!isLoading && results.length === 0 && <p className="text-gray-500 text-center p-4">No results. Try broadening your search.</p>}
                    {results.map((opp, i) => {
                        const isSaved = savedLeads.has(`Opening for ${opp.headlinerArtist} on ${opp.date}`);
                        return (
                            <div key={i} className="bg-gray-800 p-3 rounded-lg">
                                <p className="font-bold">Opening for {opp.headlinerArtist}</p>
                                <p className="text-xs text-gray-400">{new Date(opp.date).toLocaleDateString('en-US', { timeZone: 'UTC' })} at {opp.venue}, {opp.city}</p>
                                <p className="text-xs text-purple-300 mt-1">
                                    Promoter: {opp.promoterName}{opp.promoterEmail ? ` (${opp.promoterEmail})` : ''}
                                </p>
                                <div className="flex justify-between items-center mt-2">
                                    <a href={opp.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">Source <ExternalLinkIcon className="w-3 h-3 ml-1"/></a>
                                    <button onClick={() => handleSaveAsLead(opp)} disabled={isSaved} className="text-xs bg-green-600 hover:bg-green-700 text-white font-semibold py-1 px-3 rounded-md disabled:bg-gray-500">
                                        <SaveIcon className="w-3 h-3 mr-1 inline"/>
                                        {isSaved ? 'Saved' : 'Save as Lead'}
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                 </div>
            </div>
             <div>
                <h3 className="text-lg font-bold mb-2">My Current Leads</h3>
                <div className="space-y-2 max-h-[65vh] overflow-y-auto pr-2">
                    {bandGigs.filter(g => g.status === 'Lead').sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(g => (
                        <div key={g.id} className="bg-gray-800 p-3 rounded-lg">
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="font-bold">{g.eventName}</p>
                                    <p className="text-xs text-gray-400">{new Date(g.date).toLocaleDateString('en-US', { timeZone: 'UTC' })} at {g.location}</p>
                                    {g.headlinerArtist && <p className="text-xs text-purple-300 mt-1">Headliner: {g.headlinerArtist}</p>}
                                </div>
                                <button onClick={() => setGigs(prev => prev.filter(gig => gig.id !== g.id))} className="p-1 hover:bg-gray-700 rounded text-red-500"><TrashIcon className="w-4 h-4"/></button>
                            </div>

                            <div className="flex justify-between items-center mt-2 pt-2 border-t border-gray-700/50">
                                <span className="text-xs text-gray-500 truncate max-w-[150px]">{g.clientName}</span>
                                {g.sourceUrl && (
                                    <a href={g.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline flex items-center">
                                        Source <ExternalLinkIcon className="w-3 h-3 ml-1"/>
                                    </a>
                                )}
                            </div>
                        </div>
                    ))}
                    {bandGigs.filter(g => g.status === 'Lead').length === 0 && <p className="text-gray-500 text-center p-4">No leads yet. Use the finder to discover opportunities!</p>}
                </div>
             </div>
             {notification && <div className="fixed bottom-5 right-5 bg-green-500 text-white p-3 rounded-lg">{notification}</div>}
        </div>
    );
};


