// New Component for AI Email Generation
const GigEmailModal: React.FC<{
    gig: Gig,
    user: User,
    band: BandProfile,
    onClose: () => void
}> = ({ gig, user, band, onClose }) => {
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [prompt, setPrompt] = useState('Write a friendly confirmation email for this gig, including the date, time, and fee. Ask about load-in time.');
    const [isLoading, setIsLoading] = useState(false);

    // Template Management
    const [templates, setTemplates] = useLocalStorage<{name: string, subject: string, body: string}[]>('gigEmailTemplates', []);
    const [selectedTemplateName, setSelectedTemplateName] = useState('');
    const [newTemplateName, setNewTemplateName] = useState('');
    const [isTemplateMode, setIsTemplateMode] = useState(false);

    const handleGenerate = async () => {
        if(!prompt) return;
        setIsLoading(true);
        const result = await generateGigEmail(gig, user, band, prompt);
        setSubject(result.subject);
        setBody(result.body);
        setIsLoading(false);
    };

    const handleSaveTemplate = async () => {
        if (!newTemplateName || !body) return;
        setIsLoading(true);

        // Use AI to generalize the template
        const templateBody = await createEmailTemplate(body, gig);

        const newTemplate = { name: newTemplateName, subject, body: templateBody };
        setTemplates(prev => [...prev, newTemplate]);
        setNewTemplateName('');
        setIsTemplateMode(false);
        setIsLoading(false);
        alert("Template saved! Placeholders like {{Venue}} have been inserted.");
    };

    const handleLoadTemplate = (templateName: string) => {
        const template = templates.find(t => t.name === templateName);
        if (!template) return;

        // Replace placeholders with actual data
        let filledBody = template.body
            .replace(/{{Venue}}/g, gig.location)
            .replace(/{{Contact}}/g, gig.clientName)
            .replace(/{{EventName}}/g, gig.eventName)
            .replace(/{{Date}}/g, new Date(gig.date).toLocaleDateString())
            .replace(/{{Fee}}/g, `$${gig.fee}`);

        setSubject(template.subject);
        setBody(filledBody);
        setSelectedTemplateName(templateName);
    };

    const handleSend = () => {
        const mailtoLink = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
        window.open(mailtoLink, '_blank');
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-80 flex items-center justify-center p-4 z-[60]">
            <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-3xl h-[90vh] flex flex-col">
                <header className="p-4 border-b border-gray-700 flex justify-between items-center">
                    <div>
                        <h2 className="text-xl font-bold flex items-center gap-2"><MailIcon className="w-5 h-5 text-purple-400"/> Email Studio: {gig.eventName}</h2>
                        <p className="text-xs text-gray-400">To: {gig.clientName}</p>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">&times;</button>
                </header>

                <main className="flex-grow p-6 overflow-y-auto flex gap-6">
                    {/* Left Panel: AI & Templates */}
                    <div className="w-1/3 space-y-6 border-r border-gray-800 pr-4">
                        {/* AI Generator */}
                        <div className="bg-gray-800 p-4 rounded-lg">
                            <h3 className="text-sm font-bold text-purple-300 mb-2 flex items-center gap-2"><BotIcon className="w-4 h-4"/> Magic Draft</h3>
                            <textarea 
                                value={prompt} 
                                onChange={e => setPrompt(e.target.value)} 
                                className="w-full bg-gray-700 text-xs p-2 rounded mb-2 h-20" 
                                placeholder="What should this email say?"
                            />
                            <button 
                                onClick={handleGenerate} 
                                disabled={isLoading}
                                className="w-full bg-purple-600 hover:bg-purple-500 text-white text-xs font-bold py-2 rounded"
                            >
                                {isLoading ? 'Writing...' : 'Generate Draft'}
                            </button>
                        </div>

                        {/* Templates */}
                        <div className="bg-gray-800 p-4 rounded-lg">
                            <h3 className="text-sm font-bold text-blue-300 mb-2">Saved Templates</h3>
                            <select 
                                value={selectedTemplateName} 
                                onChange={e => handleLoadTemplate(e.target.value)} 
                                className="w-full bg-gray-700 text-xs p-2 rounded mb-2"
                            >
                                <option value="">Select a template...</option>
                                {templates.map(t => <option key={t.name} value={t.name}>{t.name}</option>)}
                            </select>
                            <p className="text-[10px] text-gray-500">Templates auto-adapt to this gig's details (Venue, Date, etc.).</p>
                        </div>
                    </div>

                    {/* Right Panel: Editor */}
                    <div className="w-2/3 flex flex-col gap-4">
                        <input 
                            type="text" 
                            value={subject} 
                            onChange={e => setSubject(e.target.value)} 
                            placeholder="Subject" 
                            className="bg-gray-800 p-3 rounded-lg font-bold focus:ring-2 ring-purple-500 outline-none"
                        />
                        <textarea 
                            value={body} 
                            onChange={e => setBody(e.target.value)} 
                            placeholder="Email body..." 
                            className="flex-grow bg-gray-800 p-4 rounded-lg resize-none focus:ring-2 ring-purple-500 outline-none"
                        />
                    </div>
                </main>

                <footer className="p-4 border-t border-gray-700 flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        {isTemplateMode ? (
                            <div className="flex items-center gap-2 animate-fade-in">
                                <input 
                                    type="text" 
                                    value={newTemplateName} 
                                    onChange={e => setNewTemplateName(e.target.value)} 
                                    placeholder="Template Name" 
                                    className="bg-gray-800 text-xs p-2 rounded border border-gray-600"
                                />
                                <button onClick={handleSaveTemplate} className="bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold py-2 px-3 rounded">Save</button>
                                <button onClick={() => setIsTemplateMode(false)} className="text-gray-400 text-xs hover:text-white">Cancel</button>
                            </div>
                        ) : (
                            <button onClick={() => setIsTemplateMode(true)} className="text-gray-400 hover:text-white text-xs flex items-center gap-1">
                                <SaveIcon className="w-3 h-3"/> Save as Template
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button onClick={() => {navigator.clipboard.writeText(body); alert('Copied!');}} className="bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-lg text-sm flex items-center gap-2">
                            <CopyIcon className="w-4 h-4"/> Copy
                        </button>
                        <button onClick={handleSend} className="bg-spotify-green hover:bg-green-500 text-white font-bold py-2 px-6 rounded-lg text-sm flex items-center gap-2">
                            <MailIcon className="w-4 h-4"/> Send
                        </button>
                    </div>
                </footer>
            </div>
        </div>
    );
};

const GigDetailModal: React.FC<{ gig: Gig, users: User[], onClose: () => void, onSave: (gig: Gig) => void, onDelete: (id: string) => void, setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>, setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>, allInvoices: Invoice[], bandSettings: BandSettings }> = ({ gig, users, onClose, onSave, onDelete, setInvoices, setTransactions, allInvoices, bandSettings }) => {
    const [editedGig, setEditedGig] = useState(gig);
    const [newRoleName, setNewRoleName] = useState('');
    const [notification, setNotification] = useState('');
    const [showEmailModal, setShowEmailModal] = useState(false);

    // Get active band profile safely
    const [bands] = useLocalStorage<BandProfile[]>('bands', initialBandProfiles);
    const activeBand = bands.find(b => b.id === gig.bandId) || bands[0];
    const currentUser = users[0]; // Ideally passed down properly, using first user as fallback

    const showNotification = (message: string) => {
        setNotification(message);
        setTimeout(() => setNotification(''), 3000);
    };

    const handleRoleChange = (roleId: string, updates: Partial<GigRole>) => {
        setEditedGig(prev => ({
            ...prev,
            roles: prev.roles.map(r => r.id === roleId ? {...r, ...updates} : r)
        }));
    };

    const handleAddRole = () => {
        if (!newRoleName.trim()) return;
        const newRole: GigRole = {
            id: `gr-${Date.now()}`,
            roleName: newRoleName,
            fee: 0,
            status: 'Open'
        };
        setEditedGig(prev => ({...prev, roles: [...prev.roles, newRole]}));
        setNewRoleName('');
    };

    const handleSaveAndClose = () => {
        onSave(editedGig);
        onClose();
    };

    const handleDelete = () => {
        onDelete(gig.id);
        onClose();
    };

    const handleGenerateInvoice = () => {
        const transactionId = `tx-inv-${gig.id}`;

        setTransactions(prev => {
             const newTransaction: Transaction = {
                id: transactionId,
                description: `Payment for ${gig.eventName} (${gig.clientName})`,
                amount: gig.fee,
                type: TransactionType.Income,
                category: 'Gig',
                date: gig.date,
                bandId: gig.bandId,
                gigId: gig.id,
            };
            return [...prev, newTransaction]
        });

        setInvoices(prev => {
            const newInvoice: Invoice = {
                id: `inv-${gig.id}`,
                transactionId: transactionId,
                bandId: gig.bandId,
                invoiceNumber: `${new Date(gig.date).getFullYear()}-${String(prev.length + 1).padStart(3, '0')}`,
                invoiceDate: new Date().toISOString(),
                dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // Due in 30 days
                status: 'Sent',
                issuer: {
                    name: bandSettings.issuerName,
                    address: bandSettings.issuerAddress,
                    taxId: bandSettings.issuerTaxId,
                    bankDetails: bandSettings.issuerBankDetails,
                },
                recipient: {
                    name: gig.clientName,
                    address: gig.location, // Placeholder
                },
                items: [{
                    description: `Musical performance for ${gig.eventName} on ${new Date(gig.date).toLocaleDateString()}`,
                    quantity: 1,
                    unitPrice: gig.fee
                }],
                total: gig.fee,
            };
            return [...prev, newInvoice]
        });

        showNotification('Invoice generated and income logged!');
        onSave({ ...editedGig, invoiceUrl: `#/invoices?view=inv-${gig.id}` }); // Mark as having invoice
    };

    const hasInvoice = useMemo(() => !!editedGig.invoiceUrl || allInvoices.some(inv => inv.id === `inv-${gig.id}`), [editedGig.invoiceUrl, allInvoices, gig.id]);

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center p-4 z-50">
            {notification && <div className="fixed top-5 right-5 bg-green-500 text-white p-3 rounded-lg z-50">{notification}</div>}
            <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
                 <header className="p-4 border-b border-gray-700 flex justify-between items-center">
                    <div>
                        <h2 className="text-2xl font-bold">{editedGig.eventName}</h2>
                        <p className="text-sm text-gray-400">{editedGig.clientName} - {new Date(editedGig.date).toLocaleDateString()}</p>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">&times;</button>
                </header>
                <main className="flex-grow p-6 overflow-y-auto grid grid-cols-3 gap-6">
                    {/* Left Column - Details */}
                    <div className="col-span-1 space-y-4">
                        <div><h3 className="text-sm font-bold text-gray-400">Total Fee</h3><p className="text-lg">${editedGig.fee}</p></div>
                        <div><h3 className="text-sm font-bold text-gray-400">Location</h3><p>{editedGig.location}</p></div>
                        {editedGig.headlinerArtist && (
                            <div><h3 className="text-sm font-bold text-gray-400">Headliner</h3><p>{editedGig.headlinerArtist}</p></div>
                        )}
                        {editedGig.sourceUrl && (
                            <div><h3 className="text-sm font-bold text-gray-400">Source Lead</h3><a href={editedGig.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:underline break-all">{editedGig.sourceUrl}</a></div>
                        )}
                        <div><h3 className="text-sm font-bold text-gray-400">Status</h3>
                            <select value={editedGig.status} onChange={e => setEditedGig({...editedGig, status: e.target.value as GigStatus})} className="w-full bg-gray-700 p-2 rounded-lg mt-1 text-sm">
                                {GIG_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                         <div><h3 className="text-sm font-bold text-gray-400">Notes</h3>
                            <textarea value={editedGig.notes || ''} onChange={e => setEditedGig({...editedGig, notes: e.target.value})} rows={4} className="w-full bg-gray-700 p-2 rounded-lg mt-1 text-sm"/>
                        </div>
                        <div className="space-y-2">
                             <button onClick={() => setShowEmailModal(true)} className="w-full flex items-center justify-center p-2 text-sm bg-purple-600 hover:bg-purple-700 rounded-lg"><MailIcon className="w-4 h-4 mr-2"/>Send Email</button>
                             <button onClick={() => showNotification('This feature is for demo purposes.')} className="w-full flex items-center justify-center p-2 text-sm bg-blue-600 hover:bg-blue-700 rounded-lg"><FileTextIcon className="w-4 h-4 mr-2"/>Generate Contract</button>
                             <button onClick={handleGenerateInvoice} disabled={hasInvoice} className="w-full flex items-center justify-center p-2 text-sm bg-green-600 hover:bg-green-700 rounded-lg disabled:bg-gray-500">
                                <FinancialsIcon className="w-4 h-4 mr-2"/>
                                {hasInvoice ? 'Invoice Generated' : 'Generate Invoice'}
                             </button>
                        </div>
                    </div>
                    {/* Right Column - Roles */}
                    <div className="col-span-2 bg-gray-800 p-4 rounded-lg">
                         <h3 className="text-lg font-bold flex items-center mb-4"><CollaboratorIcon className="w-5 h-5 mr-2"/>Team & Roles</h3>
                         <div className="space-y-2">
                            {editedGig.roles.map(role => {
                                const availableMembers = users.filter(u => u.primaryRole === role.roleName || u.secondaryRoles.includes(role.roleName));
