            priority: newTaskData.priority,
        };

        setTasks(prevTasks => [...prevTasks, newTask]);

        // Reset and hide form
        setNewTaskData({
            title: '',
            assignedToId: users[0]?.id || '',
            dueDate: new Date().toISOString().substring(0, 10),
            priority: TaskPriority.Medium,
        });
        setFormVisibleForStatus(null);
