                    if (release.id === changedTask!.releaseId) {
                        return {
                            ...release,
                            checklist: release.checklist.map(item =>
                                item.linkedTaskId === changedTask!.id ? { ...item, completed: destinationStatus === TaskStatus.Done } : item
                            )
                        };
                    }
                    return release;
                }));
            }

            return updatedTasks;
        });

        setDraggedTaskId(null);
        setDragOverStatus(null);
    };

