// Retry helper for API calls
const retryAI = async <T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const errorMessage = error?.message || '';
        const isQuotaExceeded = errorMessage.includes('quota') || errorMessage.includes('RESOURCE_EXHAUSTED') || errorMessage.includes('429');

        // If quota is exhausted, do not retry; fail immediately so fallbacks can trigger
        if (isQuotaExceeded) {
            console.warn("Gemini API Quota Exceeded. Skipping retries.");
            throw error;
        }

        // Check for 429 (Too Many Requests) or 503 (Service Unavailable)
        const isRateLimit = error?.status === 429 || error?.code === 429 || errorMessage.includes('429');
        const isServiceUnavailable = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServiceUnavailable)) {
            // Increase delay significantly for 429s (API limits)
            const nextDelay = isRateLimit ? Math.max(delay * 2, 4000) : delay * 2;
            console.warn(`API Busy/Limit hit (429/503). Retrying in ${nextDelay}ms... (${retries} retries left)`);
            await new Promise(res => setTimeout(res, nextDelay));
            return retryAI(operation, retries - 1, nextDelay); // Exponential backoff
        }
        throw error;
    }
};

export type EmailTone = 'Professional' | 'Casual' | 'Enthusiastic' | 'Minimalist';
export type EmailLength = 'Brief' | 'Standard' | 'Detailed';

export const generateEmail = async (
    prompt: string, 
    contactName: string, 
    tone: EmailTone, 
    length: EmailLength, 
    bandProfile: BandProfile, 
    isBulk = false,
    projectContext?: ProductionProject
): Promise<string> => {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const lengthInstruction = {
        'Brief': 'around 100 words',
        'Standard': 'around 200 words',
        'Detailed': 'around 300 words'
    };

    const projectInfo = projectContext 
      ? `
**Project Context:**
This email is regarding our upcoming project, "${projectContext.name}".
- Type: ${projectContext.type}
- Description: ${projectContext.description}
Incorporate this information into the email naturally.` 
      : '';

    const fullPrompt = `
      You are a helpful assistant for an independent band called '${bandProfile.name}'.
      Your task is to generate a professional, engaging, and friendly email.

      ${isBulk 
        ? `This is a bulk email template to be sent to multiple contacts. 
You MUST use placeholders like {{name}} for the contact's name and {{outlet}} for their publication/outlet or {{labelName}} for their record label.
The generated email should be a template that can be personalized for each recipient.`
        : `This email is for a specific contact.
**Contact Name:** ${contactName}`
      }

      **Band Name:** ${bandProfile.name}
      **Band Genre:** ${bandProfile.genre}
      ${projectInfo}

      **User's Request:**
      "${prompt}"

      **Instructions:**
      - The tone must be: ${tone}.
      - The email body should be ${lengthInstruction[length]}.
      - Keep it concise and to the point within the requested length.
      - End the email with a clear call to action if appropriate.
      - Include placeholders like "[Your Name]" for the sender to fill in.
      - Do not include a subject line unless specifically asked.
