export interface WebSource {
  uri: string;
  title: string;
}

export interface SearchResult {
  answer: string;
  sources: WebSource[];
}

export const searchWeb = async (query: string): Promise<SearchResult> => {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY environment variable not set");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await retryAI<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Answer the following question based on Google Search results: "${query}"`,
      config: {
        tools: [{googleSearch: {}}],
      },
    }));

    const answer = response.text || "";
    const sources: WebSource[] = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
        uri: chunk.web?.uri || '',
        title: chunk.web?.title || 'Untitled',
    })).filter((source: WebSource) => source.uri) || [];

    const uniqueSources = Array.from(new Map(sources.map(item => [item.uri, item])).values());

    return { answer, sources: uniqueSources };

  } catch (error) {
    console.error("Error searching web:", error);
    return {
      answer: "Sorry, I couldn't perform the search at this moment. Please check the API key and try again.",
      sources: []
    };
  }
};

