## hooks/useLocalStorage.ts

```tsx
import React, { useState, useEffect, useRef, useCallback } from 'react';

function useLocalStorage<T>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  // Use a ref to store the initial value to prevent dependency loops.
  // We only care about the initialValue passed during the FIRST render of a specific key.
  const initialValueRef = useRef(initialValue);

  // Helper to read from local storage
  const readValue = useCallback((): T => {
    if (typeof window === 'undefined') {
      return initialValueRef.current;
    }
    try {
      const item = window.localStorage.getItem(key);
      if (item) {
        return JSON.parse(item);
      } else {
        // If key doesn't exist, initialize it with default value immediately
        // This ensures subsequent reads find the data.
        // We verify the value is not undefined before writing.
        const initVal = initialValueRef.current;
        if (initVal !== undefined) {
             window.localStorage.setItem(key, JSON.stringify(initVal));
        }
        return initVal;
      }
    } catch (error) {
      console.warn(`Error reading localStorage key “${key}”:`, error);
      return initialValueRef.current;
    }
  }, [key]);

  // State to store our value
  // Pass a function to useState to ensure this only runs once per component mount
  const [storedValue, setStoredValue] = useState<T>(readValue);

  // Return a wrapped version of useState's setter function that persists the new value to localStorage.
  const setValue: React.Dispatch<React.SetStateAction<T>> = useCallback(
    (value) => {
      try {
        // Allow value to be a function so we have same API as useState
        setStoredValue((currentValue) => {
            const valueToStore = value instanceof Function ? value(currentValue) : value;

            if (typeof window !== 'undefined') {
                window.localStorage.setItem(key, JSON.stringify(valueToStore));
                // Dispatch a custom event so other hooks on the same page update
                window.dispatchEvent(new StorageEvent('storage', { key, newValue: JSON.stringify(valueToStore) }));
            }
            return valueToStore;
        });
      } catch (error) {
        console.error(`Error setting localStorage key “${key}”:`, error);
      }
    },
    [key]
  );

  // Effect to update state if the KEY changes (e.g. switching bands).
  useEffect(() => {
    setStoredValue(readValue());
  }, [key, readValue]);

  // Effect to listen for changes from other tabs/windows or same-window dispatches
  useEffect(() => {
    const handleStorageChange = (event: StorageEvent) => {
      if (event.key === key && event.newValue) {
        try {
          setStoredValue(JSON.parse(event.newValue));
        } catch (error) {
          console.error(`Error parsing storage change for key "${key}":`, error);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
    };
  }, [key]);

  return [storedValue, setValue];
}

export default useLocalStorage;
```

