                ) : (
                    <button onClick={onShowForm} className="w-full flex items-center justify-center p-2 text-gray-400 hover:bg-gray-800 hover:text-white rounded-lg transition-colors">
                        <PlusIcon className="h-4 w-4 mr-2" /> Add Task
                    </button>
                )}
            </div>
        </div>
