## hooks/useLocalStorage.ts

```tsx
import { useState, useEffect, useRef } from "react";

/**
 * A robust hook for syncing state with LocalStorage.
 * Uses lazy initialization to read once on mount.
 * Uses useEffect to write on every state change.
 */
export default function useLocalStorage<T>(key: string, initialValue: T) {
  // 1. Lazy Initialization: Read from storage only once when component mounts
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      if (typeof window === "undefined") {
        return initialValue;
      }
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key “${key}”:`, error);
      return initialValue;
    }
  });

  // 2. Synchronization: Write to storage whenever storedValue or key changes
  useEffect(() => {
    try {
      if (typeof window !== "undefined") {
        window.localStorage.setItem(key, JSON.stringify(storedValue));
      }
    } catch (error) {
      console.warn(`Error writing localStorage key “${key}”:`, error);
    }
  }, [key, storedValue]);

  // 3. Cross-Tab Sync: Listen for changes from other tabs
  useEffect(() => {
    const handleStorageChange = (event: StorageEvent) => {
      if (event.key === key && event.newValue) {
        try {
          setStoredValue(JSON.parse(event.newValue));
        } catch (error) {
          console.error("Error parsing storage event:", error);
        }
      }
    };

    if (typeof window !== "undefined") {
      window.addEventListener("storage", handleStorageChange);
      return () => window.removeEventListener("storage", handleStorageChange);
    }
  }, [key]);

  return [storedValue, setStoredValue] as const;
}
```

